using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace VisualRelay.Guards;

/// <summary>
/// Pure matcher that flags real-git-invoker fallbacks inside
/// <c>src/VisualRelay.Core/Execution</c> — the two patterns that let a caller
/// omit <see cref="VisualRelay.Core.Execution.IGitInvoker"/> and silently spawn a
/// real <c>git</c> process:
/// <list type="number">
///   <item><c>new GitInvoker(</c> object creation — a private real process launcher
///         inside a layer that must receive the invoker through its injection seam;</item>
///   <item>an <c>IGitInvoker</c> (or <c>IGitInvoker?</c>) parameter that declares a
///         default value — the <c>= null</c> that enables call-site omission and
///         triggers the runtime <c>?? new GitInvoker()</c> coalesce.</item>
/// </list>
/// <para>Allowlist is empty — after the fix there must be zero of either pattern
/// under the execution layer. The guard stays a guard-as-test; it is excluded from
/// the <c>check</c> gate and the standalone guards CLI subcommand list. Files
/// outside <c>src/VisualRelay.Core/Execution</c> (in particular <c>Init</c>,
/// the App, and the CLI) are not scanned.</para>
/// </summary>
public static class RealGitFallbackGuard
{
    /// <summary>Describes a single real-git-fallback violation (1-based <paramref name="Line"/>).</summary>
    public sealed record Violation(string Path, int Line, string Snippet, string Reason);

    private static readonly string[] SelfExemptFileNames =
        ["RealGitFallbackGuard.cs", "RealGitFallbackGuardTests.cs"];

    private const string ExecutionDir = "src/VisualRelay.Core/Execution/";

    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    // ── (Path, Source) overload ────────────────────────────────────────────

    /// <summary>
    /// Returns every real-git-fallback violation across <paramref name="files"/>,
    /// ordered by path (ordinal) then line. Only files whose path starts with
    /// <c>src/VisualRelay.Core/Execution/</c> are scanned.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(
        IEnumerable<(string Path, string Source)> files)
    {
        var violations = new List<Violation>();

        foreach (var (path, source) in files)
        {
            if (!ShouldScan(path))
                continue;

            var tree = CSharpSyntaxTree.ParseText(source, ParseOptions, path);
            ScanTree(path, tree, violations);
        }

        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    // ── (Path, SyntaxTree) overload ────────────────────────────────────────

    /// <summary>
    /// Returns every real-git-fallback violation across <paramref name="trees"/>,
    /// ordered by path (ordinal) then line. Only trees whose path starts with
    /// <c>src/VisualRelay.Core/Execution/</c> are scanned. Uses pre-parsed
    /// <see cref="SyntaxTree"/> objects instead of re-parsing string sources.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(
        IEnumerable<(string Path, SyntaxTree Tree)> trees)
    {
        var violations = new List<Violation>();

        foreach (var (path, tree) in trees)
        {
            if (!ShouldScan(path))
                continue;

            ScanTree(path, tree, violations);
        }

        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    // ── Internals ──────────────────────────────────────────────────────────

    private static bool ShouldScan(string path)
    {
        var fileName = Path.GetFileName(path);
        if (SelfExemptFileNames.Contains(fileName))
            return false;

        return path.StartsWith(ExecutionDir, StringComparison.Ordinal);
    }

    private static void ScanTree(string path, SyntaxTree tree, List<Violation> sink)
    {
        var text = tree.GetText();
        var root = tree.GetRoot();

        // Rule 1 — new GitInvoker( object creation.
        foreach (var creation in root.DescendantNodes().OfType<ObjectCreationExpressionSyntax>())
        {
            if (IsGitInvokerType(creation.Type))
            {
                var line = LineOf(text, creation.SpanStart);
                sink.Add(new Violation(path, line, SnippetOf(text, line),
                    "new GitInvoker() object creation inside the execution layer (inject IGitInvoker instead)"));
            }
        }

        // Rule 2 — IGitInvoker / IGitInvoker? parameter with a default value.
        foreach (var param in root.DescendantNodes().OfType<ParameterSyntax>())
        {
            if (param.Default is not null && IsIGitInvokerType(param.Type))
            {
                var line = LineOf(text, param.SpanStart);
                sink.Add(new Violation(path, line, SnippetOf(text, line),
                    "IGitInvoker parameter with a default value (make it required, non-optional)"));
            }
        }
    }

    private static bool IsGitInvokerType(TypeSyntax type) => type switch
    {
        IdentifierNameSyntax id => id.Identifier.Text == "GitInvoker",
        QualifiedNameSyntax qn => qn.Right.Identifier.Text == "GitInvoker",
        AliasQualifiedNameSyntax aq => aq.Name.Identifier.Text == "GitInvoker",
        _ => false,
    };

    private static bool IsIGitInvokerType(TypeSyntax? type) => type switch
    {
        null => false,
        IdentifierNameSyntax id => id.Identifier.Text is "IGitInvoker",
        NullableTypeSyntax n => n.ElementType is IdentifierNameSyntax id && id.Identifier.Text is "IGitInvoker",
        QualifiedNameSyntax qn => qn.Right.Identifier.Text is "IGitInvoker",
        _ => false,
    };

    private static int LineOf(SourceText text, int position) =>
        text.Lines.GetLinePosition(position).Line + 1;

    private static string SnippetOf(SourceText text, int line)
    {
        var s = text.Lines[line - 1].ToString().Trim();
        return s.Length <= 200 ? s : s[..200];
    }
}

using VisualRelay.Guards;

namespace VisualRelay.Tests;

/// <summary>
/// Guard-as-test for <see cref="RealGitFallbackGuard"/>. The guard flags two
/// patterns under <c>src/VisualRelay.Core/Execution</c>:
/// <list type="number">
///   <item><c>new GitInvoker(</c> object creation — a private real process launcher
///         inside a layer that must receive the invoker through its injection seam;</item>
///   <item>an <c>IGitInvoker</c> (or <c>IGitInvoker?</c>) parameter that declares a
///         default value — the <c>= null</c> that enables call-site omission.</item>
/// </list>
/// <para>The allowlist is empty. After the fix the live-tree test must assert zero
/// violations in <c>src/VisualRelay.Core/Execution</c>. The inline-snippet tests
/// below prove the matcher has teeth against both patterns.</para>
/// </summary>
public sealed class RealGitFallbackGuardTests
{
    private readonly CachedSyntaxTreesFixture _trees;

    public RealGitFallbackGuardTests(CachedSyntaxTreesFixture trees)
    {
        _trees = trees;
    }

    // ── Inline-snippet unit tests ──────────────────────────────────────────

    /// <summary>
    /// Teeth: <c>new GitInvoker()</c> inside a source file under
    /// <c>src/VisualRelay.Core/Execution</c> is flagged.
    /// </summary>
    [Fact]
    public void NewGitInvoker_InExecutionLayer_IsFlagged()
    {
        const string source = """
            using VisualRelay.Core.Execution;
            class C { void M() { var gi = new GitInvoker(); } }
            """;

        var violations = RealGitFallbackGuard.FindViolations(
            [("src/VisualRelay.Core/Execution/Foo.cs", source)]);

        var v = Assert.Single(violations);
        Assert.Contains("new GitInvoker()", v.Reason, StringComparison.Ordinal);
    }

    /// <summary>
    /// Teeth: an <c>IGitInvoker?</c> parameter with <c>= null</c> default
    /// inside the execution layer is flagged.
    /// </summary>
    [Fact]
    public void OptionalIGitInvokerParam_InExecutionLayer_IsFlagged()
    {
        const string source = """
            using VisualRelay.Core.Execution;
            class C { void M(IGitInvoker? gitInvoker = null) { } }
            """;

        var violations = RealGitFallbackGuard.FindViolations(
            [("src/VisualRelay.Core/Execution/Foo.cs", source)]);

        var v = Assert.Single(violations);
        Assert.Contains("default value", v.Reason, StringComparison.Ordinal);
    }

    /// <summary>
    /// <c>new GitInvoker()</c> outside <c>src/VisualRelay.Core/Execution</c>
    /// (e.g. in <c>src/VisualRelay.Core/Init</c>) is NOT flagged — the guard
    /// only scans the execution layer.
    /// </summary>
    [Fact]
    public void NewGitInvoker_OutsideExecutionLayer_IsNotFlagged()
    {
        const string source = """
            using VisualRelay.Core.Execution;
            class C { void M() { var gi = new GitInvoker(); } }
            """;

        var violations = RealGitFallbackGuard.FindViolations(
            [("src/VisualRelay.Core/Init/Foo.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// An optional <c>IGitInvoker?</c> parameter outside the execution layer
    /// (e.g. in Init) is NOT flagged — only the execution layer is guarded.
    /// </summary>
    [Fact]
    public void OptionalIGitInvokerParam_OutsideExecutionLayer_IsNotFlagged()
    {
        const string source = """
            using VisualRelay.Core.Execution;
            class C { void M(IGitInvoker? gitInvoker = null) { } }
            """;

        var violations = RealGitFallbackGuard.FindViolations(
            [("src/VisualRelay.Core/Init/Foo.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// A required <c>IGitInvoker</c> parameter (no default) is NOT flagged —
    /// only optional defaults are violations.
    /// </summary>
    [Fact]
    public void RequiredIGitInvokerParam_IsNotFlagged()
    {
        const string source = """
            using VisualRelay.Core.Execution;
            class C { void M(IGitInvoker gitInvoker) { } }
            """;

        var violations = RealGitFallbackGuard.FindViolations(
            [("src/VisualRelay.Core/Execution/Foo.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// Happy path: clean code with no <c>new GitInvoker(</c> and no optional
    /// IGitInvoker params produces zero violations.
    /// </summary>
    [Fact]
    public void CleanCode_WithNoViolations_ReportsZero()
    {
        const string source = """
            using VisualRelay.Core.Execution;
            class C
            {
                readonly IGitInvoker _git;
                C(IGitInvoker git) => _git = git;
                void M() { _git.RunAsync("", [], default); }
            }
            """;

        var violations = RealGitFallbackGuard.FindViolations(
            [("src/VisualRelay.Core/Execution/Foo.cs", source)]);

        Assert.Empty(violations);
    }

    // ── Live-tree test ─────────────────────────────────────────────────────

    /// <summary>
    /// The live enforcing gate: every file under <c>src/VisualRelay.Core/Execution</c>
    /// must have zero <c>new GitInvoker(</c> and zero optional-IGitInvoker defaults.
    /// This is the in-suite mirror of <c>./visual-relay audit di-bypass</c> for the
    /// execution layer specifically.
    /// </summary>
    [Fact]
    public void LiveTree_HasNoRealGitFallbacks()
    {
        var trees = _trees.AllTrees
            .Where(t => t.RelativePath.StartsWith("src/", StringComparison.Ordinal))
            .ToList();

        var violations = RealGitFallbackGuard.FindViolations(trees);

        Assert.True(violations.Count == 0,
            "RealGitFallbackGuard found new GitInvoker() or optional IGitInvoker params " +
            "in src/VisualRelay.Core/Execution (inject IGitInvoker instead, make it required):\n" +
            string.Join("\n", violations.Select(v => $"{v.Path}:{v.Line}: {v.Reason} — {v.Snippet}")));
    }
}

using VisualRelay.Core.Execution;

namespace VisualRelay.Tests;

/// <summary>
/// Wraps an inner <see cref="IGitInvoker"/> and records every argument vector
/// passed to <see cref="RunAsync"/>. Use with <see cref="GitSim.GitSim"/> to
/// prove that every git probe in a driver run flows through the injected invoker
/// rather than a private <c>new GitInvoker()</c> fallback.
/// </summary>
public sealed class RecordingGitInvoker : IGitInvoker
{
    private readonly IGitInvoker _inner;
    private readonly List<string[]> _calls = [];

    public RecordingGitInvoker(IGitInvoker inner)
    {
        _inner = inner;
    }

    /// <summary>Every argument vector recorded, in call order.</summary>
    public IReadOnlyList<string[]> Calls => _calls;

    /// <summary>True when any recorded call's argument vector contains every element of <paramref name="args"/>.</summary>
    public bool RecordedCall(string[] args) =>
        _calls.Any(c => args.All(a => c.Contains(a, StringComparer.Ordinal)));

    public async Task<(int ExitCode, string Output, bool TimedOut)> RunAsync(
        string rootPath,
        IEnumerable<string> arguments,
        CancellationToken cancellationToken,
        TimeSpan? timeout = null,
        IReadOnlyDictionary<string, string>? environment = null,
        CancellationToken killToken = default,
        Action<string>? onActivity = null)
    {
        var args = arguments.ToArray();
        _calls.Add(args);
        return await _inner.RunAsync(rootPath, arguments, cancellationToken,
            timeout, environment, killToken, onActivity);
    }
}

