/// <summary>
/// Proves that the stage-4 early-implementation probe flows through the
/// INJECTED <see cref="IGitInvoker"/> rather than a private
/// <c>new GitInvoker()</c> fallback. Wraps a <see cref="GitSimEngine"/> in a
/// <see cref="RecordingGitInvoker"/>, drives one clean happy-path run, and
/// asserts the recorded argument vectors include
/// <c>rev-parse --is-inside-work-tree</c>.
/// </summary>
[Fact]
public async Task EarlyImplementationProbe_UsesInjectedGitInvoker()
{
    using var repo = TestRepository.Create();
    repo.WriteConfig("dotnet test", []);
    repo.WriteTask("probe-test", "# Probe test\n");
    var sim = InitGitRepo(repo);

    var recorder = new RecordingGitInvoker(sim);

    var runner = new ArtifactWritingSubagentRunner();
    runner.SeedHappyPath("src/status.cs", "tests/status.tests.cs");

    var driver = new RelayDriver(
        RelayDriverDependencies.ForTests(runner,
            new ScriptedTestRunner(new TestRunResult(1, "red"), new TestRunResult(0, "green")),
            new InMemoryRelayEventSink(), gitInvoker: recorder),
        RelayDriverOptions.NoGitCommit);

    var outcome = await driver.RunTaskAsync(repo.Root, "probe-test");
    Assert.Equal(RelayTaskOutcomeStatus.Committed, outcome.Status);

    Assert.True(recorder.RecordedCall(["rev-parse", "--is-inside-work-tree"]),
        "stage-4 early-implementation probe must flow through the injected IGitInvoker");
}

private static GitSimEngine InitGitRepo(TestRepository repo)
{
    var sim = RelayDriverTestHelpers.InitSim(repo);
    sim.Seed(repo.Root, "src/status.cs", "old\n");
    sim.Commit(repo.Root, "chore: seed repo");
    return sim;
}

